-- seed_catalog_v2.sql — Mega catalog: oPhysics, Walter Fendt,
-- Physics Classroom, Concord Consortium, Falstad, BioInteractive
-- ================================================================
-- author_tenant_name va explícito en cada fila: la columna es NOT NULL
-- SIN DEFAULT y con STRICT_TRANS_TABLES (producción: MariaDB 11.8) el
-- INSERT entero aborta con ERROR 1364 si se omite. Valor '' = el mismo
-- que escribe la app para recursos de comunidad (api/resources.php).

-- ── oPhysics (Tom Walsh) — Free for education ──

-- ── Walter Fendt — HTML5 Physics/Math Applets ──

-- ── The Physics Classroom — Free Interactives ──

-- ── Concord Consortium (Lab) — Open Source HTML5 ──

-- ── Falstad — HTML5 Circuit/Math Sims ──

-- ── BioInteractive (HHMI) — Biology ──

-- ── GeoGebra extras — Math ──

-- ── Tags for new resources ──
SELECT id, 'simulation' FROM resources WHERE source_name IN ('oPhysics','Walter Fendt','The Physics Classroom','Falstad') AND id > 38;
SELECT id, 'interactive' FROM resources WHERE id > 38;
SELECT id, 'free' FROM resources WHERE id > 38;
SELECT id, LOWER(source_name) FROM resources WHERE source_name IS NOT NULL AND id > 38;
